-- =============================================================================================
-- Hand-written below this line: template text checks, archiving final; runs created OPEN from
-- an active template for the assignee's own shift (if any); items only while the run is open,
-- a failed check needs a note, answer times set by the database; OPEN -> SUBMITTED (every item
-- answered) -> VERIFIED (by someone other than the assignee) or back to OPEN with a note, or
-- OPEN/SUBMITTED -> CANCELLED with a reason; final states never change.
-- See docs/architecture/DATA_MODEL.md section 10 (Staff operations).
-- =============================================================================================

ALTER TABLE "checklist_templates" ADD CONSTRAINT "checklist_templates_text"
  CHECK ("title" = btrim("title") AND length("title") BETWEEN 1 AND 120
         AND cardinality("items") BETWEEN 1 AND 50
         AND array_position("items", NULL) IS NULL);
ALTER TABLE "checklist_templates" ADD CONSTRAINT "checklist_templates_archived"
  CHECK (("status" = 'ARCHIVED') = ("archived_at" IS NOT NULL));

CREATE FUNCTION app_checklist_items_valid(items text[]) RETURNS boolean
  LANGUAGE sql IMMUTABLE
  AS $$ SELECT bool_and(i = btrim(i) AND length(i) BETWEEN 1 AND 200) FROM unnest(items) AS i $$;
ALTER TABLE "checklist_templates" ADD CONSTRAINT "checklist_templates_items"
  CHECK (app_checklist_items_valid("items"));

CREATE FUNCTION app_checklist_template_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW."status" <> 'ACTIVE' THEN
      RAISE EXCEPTION 'templates start active' USING ERRCODE = 'check_violation';
    END IF;
    NEW."created_at" := now();
    NEW."archived_at" := NULL;
    RETURN NEW;
  END IF;
  IF OLD."status" = 'ARCHIVED' THEN
    RAISE EXCEPTION 'template % is archived and no longer changes', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW."organisation_id", NEW."property_id", NEW."created_by_user_id", NEW."created_at")
     IS DISTINCT FROM (OLD."organisation_id", OLD."property_id", OLD."created_by_user_id", OLD."created_at") THEN
    RAISE EXCEPTION 'template % stays at its property', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  NEW."archived_at" := CASE WHEN NEW."status" = 'ARCHIVED' THEN now() ELSE NULL END;
  RETURN NEW;
END
$$;

CREATE TRIGGER "checklist_templates_guard"
  BEFORE INSERT OR UPDATE ON "checklist_templates"
  FOR EACH ROW EXECUTE FUNCTION app_checklist_template_guard();

ALTER TABLE "checklist_runs" ADD CONSTRAINT "checklist_runs_text"
  CHECK ("title" = btrim("title") AND length("title") BETWEEN 1 AND 120
         AND ("status_note" IS NULL OR ("status_note" = btrim("status_note") AND length("status_note") BETWEEN 1 AND 1000)));
ALTER TABLE "checklist_runs" ADD CONSTRAINT "checklist_runs_status"
  CHECK (("status" IN ('SUBMITTED', 'VERIFIED')) = ("submitted_at" IS NOT NULL)
         AND ("status" = 'VERIFIED') = ("verified_at" IS NOT NULL)
         AND ("verified_at" IS NULL) = ("verified_by_user_id" IS NULL)
         AND ("status" <> 'CANCELLED' OR "status_note" IS NOT NULL));

CREATE FUNCTION app_checklist_run_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  transition text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW."status" <> 'OPEN' THEN
      RAISE EXCEPTION 'checklists start open' USING ERRCODE = 'check_violation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM "checklist_templates" WHERE "id" = NEW."template_id" AND "status" = 'ACTIVE') THEN
      RAISE EXCEPTION 'the template is archived' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW."shift_id" IS NOT NULL AND NOT EXISTS (
         SELECT 1 FROM "shifts" WHERE "id" = NEW."shift_id" AND "user_id" = NEW."assigned_to_user_id"
            AND "status" IN ('SCHEDULED', 'STARTED')) THEN
      RAISE EXCEPTION 'a checklist goes with a live shift of the same person' USING ERRCODE = 'check_violation';
    END IF;
    NEW."created_at" := now();
    NEW."submitted_at" := NULL;
    NEW."verified_at" := NULL;
    NEW."verified_by_user_id" := NULL;
    NEW."status_note" := NULL;
    RETURN NEW;
  END IF;
  IF OLD."status" IN ('VERIFIED', 'CANCELLED') THEN
    RAISE EXCEPTION 'checklist % is % and no longer changes', OLD."id", lower(OLD."status"::text)
      USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW."organisation_id", NEW."property_id", NEW."template_id", NEW."title", NEW."assigned_to_user_id",
      NEW."shift_id", NEW."created_by_user_id", NEW."created_at")
     IS DISTINCT FROM
     (OLD."organisation_id", OLD."property_id", OLD."template_id", OLD."title", OLD."assigned_to_user_id",
      OLD."shift_id", OLD."created_by_user_id", OLD."created_at") THEN
    RAISE EXCEPTION 'checklist % keeps its template, person and shift', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  NEW."submitted_at" := OLD."submitted_at";
  NEW."verified_at" := OLD."verified_at";
  NEW."verified_by_user_id" := OLD."verified_by_user_id";
  IF NEW."status" = OLD."status" THEN
    NEW."status_note" := OLD."status_note";
    RETURN NEW;
  END IF;
  transition := OLD."status" || '>' || NEW."status";
  IF transition NOT IN ('OPEN>SUBMITTED', 'SUBMITTED>VERIFIED', 'SUBMITTED>OPEN', 'OPEN>CANCELLED', 'SUBMITTED>CANCELLED') THEN
    RAISE EXCEPTION 'a checklist cannot go from % to %', lower(OLD."status"::text), lower(NEW."status"::text)
      USING ERRCODE = 'check_violation';
  END IF;
  IF transition = 'OPEN>SUBMITTED' THEN
    IF EXISTS (SELECT 1 FROM "checklist_run_items" WHERE "run_id" = OLD."id" AND "result" IS NULL) THEN
      RAISE EXCEPTION 'answer every check before submitting' USING ERRCODE = 'check_violation';
    END IF;
    NEW."submitted_at" := now();
    NEW."status_note" := NULL;
  ELSIF transition = 'SUBMITTED>VERIFIED' THEN
    IF app_current_user_id() IS NULL OR app_current_user_id() = OLD."assigned_to_user_id" THEN
      RAISE EXCEPTION 'a checklist is verified by someone other than the person who did it'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW."verified_at" := now();
    NEW."verified_by_user_id" := app_current_user_id();
    NEW."status_note" := NULL;
  ELSIF transition = 'SUBMITTED>OPEN' THEN
    IF NEW."status_note" IS NULL THEN
      RAISE EXCEPTION 'say why the checklist is returned' USING ERRCODE = 'check_violation';
    END IF;
    NEW."submitted_at" := NULL;
  ELSIF NEW."status" = 'CANCELLED' AND NEW."status_note" IS NULL THEN
    RAISE EXCEPTION 'give a reason to cancel the checklist' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."status" = 'CANCELLED' THEN
    NEW."submitted_at" := NULL;
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "checklist_runs_guard"
  BEFORE INSERT OR UPDATE ON "checklist_runs"
  FOR EACH ROW EXECUTE FUNCTION app_checklist_run_guard();

ALTER TABLE "checklist_run_items" ADD CONSTRAINT "checklist_run_items_text"
  CHECK ("position" BETWEEN 1 AND 50
         AND "text" = btrim("text") AND length("text") BETWEEN 1 AND 200
         AND ("note" IS NULL OR ("note" = btrim("note") AND length("note") BETWEEN 1 AND 1000)));
ALTER TABLE "checklist_run_items" ADD CONSTRAINT "checklist_run_items_answer"
  CHECK (("result" IS NULL) = ("answered_at" IS NULL)
         AND ("answered_at" IS NULL) = ("answered_by_user_id" IS NULL)
         AND ("result" IS DISTINCT FROM 'FAIL' OR "note" IS NOT NULL));

CREATE FUNCTION app_checklist_item_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM "checklist_runs" WHERE "id" = NEW."run_id" AND "status" = 'OPEN') THEN
    RAISE EXCEPTION 'checks are answered only while the checklist is open' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'INSERT' THEN
    NEW."result" := NULL;
    NEW."note" := NULL;
    NEW."answered_at" := NULL;
    NEW."answered_by_user_id" := NULL;
    RETURN NEW;
  END IF;
  IF (NEW."organisation_id", NEW."property_id", NEW."run_id", NEW."position", NEW."text")
     IS DISTINCT FROM (OLD."organisation_id", OLD."property_id", OLD."run_id", OLD."position", OLD."text") THEN
    RAISE EXCEPTION 'a check keeps its wording and place' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."result" IS NULL THEN
    NEW."answered_at" := NULL;
    NEW."answered_by_user_id" := NULL;
  ELSE
    NEW."answered_at" := now();
    NEW."answered_by_user_id" := app_current_user_id();
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "checklist_run_items_guard"
  BEFORE INSERT OR UPDATE ON "checklist_run_items"
  FOR EACH ROW EXECUTE FUNCTION app_checklist_item_guard();

DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['checklist_templates', 'checklist_runs', 'checklist_run_items'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR SELECT USING (organisation_id = app_current_organisation_id())', t || '_select', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR INSERT WITH CHECK (organisation_id = app_current_organisation_id())', t || '_insert', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR UPDATE USING (organisation_id = app_current_organisation_id()) WITH CHECK (organisation_id = app_current_organisation_id())', t || '_update', t);
  END LOOP;
END
$$;

REVOKE ALL ON "checklist_templates", "checklist_runs", "checklist_run_items" FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE ON "checklist_templates", "checklist_runs", "checklist_run_items" TO veyra_app;
